package com.dappunq.controller; import com.dappunq.model.valuation.ValuationDomainException; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice public class ValuationExceptionHandler { @ExceptionHandler(ValuationDomainException.class) ResponseEntity<Map<String,String>> invalid(ValuationDomainException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));} @ExceptionHandler(NoSuchElementException.class) ResponseEntity<Map<String,String>> missing(NoSuchElementException e){return ResponseEntity.status(404).body(Map.of("message",e.getMessage()));} }
